+package notation
+
+import (
+	"bytes"
+	"encoding/json"
+	"fmt"
+	"os"
+	"path/filepath"
+	"sort"
+	"strconv"
+	"strings"
+
+	"github.com/Open-MBEE/OpenSysML/tools/oracle/baseline"
+)
+
+const (
+	baselinePath    = "docs/project/graphical-notation-census-baseline.json"
+	censusDocPath   = "docs/project/graphical-notation-census.md"
+	defaultTextPath = "build/spec-docs/sysml.txt"
+	specPinPath     = "build/spec-docs/pdf/.pilot-pin"
+	rowsPath        = "build/graphical-notation-census/rows.md"
+)
+
+// Row is one production with its verdict.
+type Row struct {
+	Production
+	Adjudication
+}
+
+// Source records which specification text the census measured.
+type Source struct {
+	PilotTag      string `json:"pilotTag"`
+	ReleaseCommit string `json:"releaseCommit"`
+	Text          string `json:"text"`
+	Clause        string `json:"clause"`
+}
+
+// Counts are the verdict counts of a set of rows.
+type Counts struct {
+	Productions   int `json:"productions"`
+	Drawn         int `json:"drawn"`
+	Approximate   int `json:"approximate"`
+	Undrawn       int `json:"undrawn"`
+	NotApplicable int `json:"notApplicable"`
+}
+
+func (c *Counts) add(v Verdict) {
+	c.Productions++
+	switch v {
+	case VerdictDrawn:
+		c.Drawn++
+	case VerdictApproximate:
+		c.Approximate++
+	case VerdictUndrawn:
+		c.Undrawn++
+	case VerdictNotApplicable:
+		c.NotApplicable++
+	}
+}
+
+// Totals are the census-wide figures.
+type Totals struct {
+	Statements        int `json:"statements"`
+	PartialStatements int `json:"partialStatements"`
+	Counts
+}
+
+// ClauseCounts are one sub-clause's figures.
+type ClauseCounts struct {
+	Number     string `json:"number"`
+	Title      string `json:"title"`
+	Statements int    `json:"statements"`
+	Counts
+}
+
+// Gap is a row the census does not find drawn, with its reason.
+type Gap struct {
+	Clause   string   `json:"clause"`
+	Name     string   `json:"name"`
+	Partial  bool     `json:"partial,omitempty"`
+	Category Category `json:"category"`
+	Verdict  Verdict  `json:"verdict"`
+	Package  string   `json:"package,omitempty"`
+	Reason   string   `json:"reason"`
+}
+
+// Baseline is the committed census: the source, the totals, the per-clause
+// and per-category counts, and every row that is not drawn.
+type Baseline struct {
+	Source     Source         `json:"source"`
+	Totals     Totals         `json:"totals"`
+	Categories map[string]int `json:"categories"`
+	Clauses    []ClauseCounts `json:"clauses"`
+	NonDrawn   []Gap          `json:"nonDrawn"`
+}
+
+// Census is a measured census: the grammar and one row per production.
+type Census struct {
+	Grammar *Grammar
+	Rows    []Row
+}
+
+// Measure extracts the grammar from the rendered text and adjudicates every
+// production. Every production needs a verdict and every static verdict a
+// production, so a changed specification fails rather than shifts the census.
+func Measure(root, text string) (*Census, error) {
+	content, err := os.ReadFile(text) // #nosec G304 -- the rendered specification text, named on the command line
+	if err != nil {
+		return nil, err
+	}
+	g, err := Extract(string(content))
+	if err != nil {
+		return nil, fmt.Errorf("%s: %w", text, err)
+	}
+	edges, err := ReadNotationTable(root)
+	if err != nil {
+		return nil, err
+	}
+	c := &Census{Grammar: g}
+	var problems []string
+	seen := map[string]bool{}
+	for _, p := range g.Productions {
+		seen[p.Name] = true
+		adj, err := Adjudicate(p.Name, edges)
+		if err != nil {
+			problems = append(problems, err.Error())
+			continue
+		}
+		c.Rows = append(c.Rows, Row{Production: p, Adjudication: adj})
+	}
+	for _, name := range AdjudicatedNames() {
+		if !seen[name] {
+			problems = append(problems, fmt.Sprintf("the verdict table adjudicates %s, which §8.2.3 no longer states", name))
+		}
+	}
+	for _, name := range edges.Names() {
+		if !seen[name] {
+			problems = append(problems, fmt.Sprintf("the notation table adjudicates %s, which §8.2.3 does not state", name))
+		}
+	}
+	if len(problems) > 0 {
+		sort.Strings(problems)
+		return nil, fmt.Errorf("the census and the specification text disagree:\n  %s", strings.Join(problems, "\n  "))
+	}
+	return c, nil
+}
+
+// Baseline folds the census into the committed shape under the given source.
+func (c *Census) Baseline(source Source) *Baseline {
+	b := &Baseline{Source: source, Categories: map[string]int{}}
+	b.Totals.Statements = len(c.Grammar.Statements)
+	b.Totals.PartialStatements = c.Grammar.Partials()
+	byClause := map[string]int{}
+	for _, cl := range c.Grammar.Clauses {
+		byClause[cl.Number] = len(b.Clauses)
+		b.Clauses = append(b.Clauses, ClauseCounts{Number: cl.Number, Title: cl.Title, Statements: cl.Statements})
+	}
+	for _, r := range c.Rows {
+		b.Totals.add(r.Verdict)
+		b.Clauses[byClause[r.Clause]].add(r.Verdict)
+		b.Categories[string(r.Category)]++
+		if r.Verdict != VerdictDrawn {
+			b.NonDrawn = append(b.NonDrawn, Gap{Clause: r.Clause, Name: r.Name, Partial: r.Partial, Category: r.Category,
+				Verdict: r.Verdict, Package: workPackage(r), Reason: r.Reason})
+		}
+	}
+	return b
+}
+
+// Work packages group the gaps for follow-up work, one package each.
+var packageTitles = []struct{ Letter, Title string }{
+	{"A", "§8.2.3.26 view frame and §8.2.3.4 annotation nodes"},
+	{"B", "§8.2.3.17–.18 action and state node forms"},
+	{"C", "§8.2.3.3/.13 n-ary dots and §8.2.3.16 flow-on-connection"},
+	{"D", "§8.2.3.9 sequence glyphs"},
+	{"E", "§8.2.3.2 textual-compartment greying"},
+	{"F", "everything else"},
+}
+
+func workPackage(r Row) string {
+	if r.Verdict != VerdictUndrawn && r.Verdict != VerdictApproximate {
+		return ""
+	}
+	switch {
+	case r.Clause == "8.2.3.4", r.Name == "root-view", r.Name == "framed-view", strings.HasPrefix(r.Name, "view-frame-"):
+		return "A"
+	case r.Clause == "8.2.3.17", r.Clause == "8.2.3.18":
+		return "B"
+	case strings.HasPrefix(r.Name, "n-ary-"), r.Name == "cdot-label", r.Name == "flow-on-connection",
+		strings.HasSuffix(r.Name, "-node-r"), strings.HasSuffix(r.Name, "-node-l"):
+		return "C"
+	case r.Clause == "8.2.3.9", r.Name == "message":
+		return "D"
+	case r.Name == "element-inside-textual-compartment", r.Name == "ellipsis-at-lower-left-corner":
+		return "E"
+	}
+	return "F"
+}
+
+// ReadSource reads the pins the census records: the pilot tag scripts/pilot-pin.sh
+// carries and the release commit the downloaded PDFs were rendered from.
+func ReadSource(root, text string) (Source, error) {
+	pin, err := baseline.ReadPin(root)
+	if err != nil {
+		return Source{}, err
+	}
+	content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(specPinPath))) // #nosec G304 -- fixed repository path
+	if err != nil {
+		return Source{}, err
+	}
+	fields := strings.Fields(string(content))
+	if len(fields) < 2 || fields[0] != pin.Tag {
+		return Source{}, fmt.Errorf("%s pins %q but %s pins %s: re-run scripts/download-spec-examples.sh", specPinPath, strings.TrimSpace(string(content)), baseline.PinPath, pin.Tag)
+	}
+	return Source{PilotTag: pin.Tag, ReleaseCommit: fields[1], Text: text, Clause: "8.2.3"}, nil
+}
+
+func loadBaseline(root string) (*Baseline, error) {
+	content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(baselinePath))) // #nosec G304 -- fixed repository path
+	if err != nil {
+		return nil, err
+	}
+	var b Baseline
+	if err := json.Unmarshal(content, &b); err != nil {
+		return nil, fmt.Errorf("%s: %w", baselinePath, err)
+	}
+	return &b, nil
+}
+
+func encodeBaseline(b *Baseline) ([]byte, error) {
+	var buf bytes.Buffer
+	enc := json.NewEncoder(&buf)
+	enc.SetEscapeHTML(false)
+	enc.SetIndent("", "  ")
+	if err := enc.Encode(b); err != nil {
+		return nil, err
+	}
+	return buf.Bytes(), nil
+}
+
+func writeBaseline(root string, b *Baseline) error {
+	data, err := encodeBaseline(b)
+	if err != nil {
+		return err
+	}
+	return os.WriteFile(filepath.Join(root, filepath.FromSlash(baselinePath)), data, 0o644) // #nosec G306 -- a committed documentation file
+}
+
+// validate checks the baseline is internally consistent: known verdicts and
+// categories, clause counts summing to the totals, the non-drawn rows sorted
+// and matching the counts.
+func (b *Baseline) validate() error {
+	var problems []string
+	if b.Source.PilotTag == "" || b.Source.ReleaseCommit == "" || b.Source.Clause != "8.2.3" {
+		problems = append(problems, "the source records no pilot tag, release commit or clause 8.2.3")
+	}
+	var sum Counts
+	var statements int
+	for i, c := range b.Clauses {
+		if c.Number != fmt.Sprintf("8.2.3.%d", i+1) {
+			problems = append(problems, fmt.Sprintf("clause %d is %s", i+1, c.Number))
+		}
+		if c.Drawn+c.Approximate+c.Undrawn+c.NotApplicable != c.Productions {
+			problems = append(problems, fmt.Sprintf("%s: the verdicts do not sum to %d productions", c.Number, c.Productions))
+		}
+		sum.Productions += c.Productions
+		sum.Drawn += c.Drawn
+		sum.Approximate += c.Approximate
+		sum.Undrawn += c.Undrawn
+		sum.NotApplicable += c.NotApplicable
+		statements += c.Statements
+	}
+	if len(b.Clauses) != clauseCount {
+		problems = append(problems, fmt.Sprintf("%d clauses, want %d", len(b.Clauses), clauseCount))
+	}
+	if sum != b.Totals.Counts || statements != b.Totals.Statements {
+		problems = append(problems, "the clause counts do not sum to the totals")
+	}
+	categories := 0
+	for name, n := range b.Categories {
+		if !knownCategory(Category(name)) {
+			problems = append(problems, fmt.Sprintf("unknown category %q", name))
+		}
+		categories += n
+	}
+	if categories != b.Totals.Productions {
+		problems = append(problems, "the category counts do not sum to the productions")
+	}
+	var gaps Counts
+	for i, g := range b.NonDrawn {
+		if g.Verdict == VerdictDrawn || !knownVerdict(g.Verdict) {
+			problems = append(problems, fmt.Sprintf("%s: a non-drawn row has verdict %q", g.Name, g.Verdict))
+		}
+		if !knownCategory(g.Category) {
+			problems = append(problems, fmt.Sprintf("%s: unknown category %q", g.Name, g.Category))
+		}
+		if g.Reason == "" {
+			problems = append(problems, fmt.Sprintf("%s: no reason", g.Name))
+		}
+		if (g.Package != "") != (g.Verdict == VerdictUndrawn || g.Verdict == VerdictApproximate) {
+			problems = append(problems, fmt.Sprintf("%s: an undrawn or approximate row has a work package, the others none", g.Name))
+		}
+		if i > 0 && !gapLess(b.NonDrawn[i-1], g) {
+			problems = append(problems, fmt.Sprintf("%s: the non-drawn rows are not sorted by clause then name", g.Name))
+		}
+		gaps.add(g.Verdict)
+	}
+	if gaps.Approximate != b.Totals.Approximate || gaps.Undrawn != b.Totals.Undrawn || gaps.NotApplicable != b.Totals.NotApplicable {
+		problems = append(problems, "the non-drawn rows do not match the totals")
+	}
+	if len(problems) == 0 {
+		return nil
+	}
+	return fmt.Errorf("%s is inconsistent:\n  %s", baselinePath, strings.Join(problems, "\n  "))
+}
+
+func knownVerdict(v Verdict) bool {
+	for _, k := range Verdicts {
+		if k == v {
+			return true
+		}
+	}
+	return false
+}
+
+func knownCategory(c Category) bool {
+	for _, k := range Categories {
+		if k == c {
+			return true
+		}
+	}
+	return false
+}
+
+// gapLess orders gaps by clause number then name, the order the baseline keeps.
+func gapLess(a, b Gap) bool {
+	if a.Clause != b.Clause {
+		return clauseIndex(a.Clause) < clauseIndex(b.Clause)
+	}
+	return a.Name < b.Name
+}
+
+func clauseIndex(number string) int {
+	n, err := strconv.Atoi(strings.TrimPrefix(number, clausePrefix))
+	if err != nil {
+		return 0
+	}
+	return n
+}
+
+func (b *Baseline) sortNonDrawn() {
+	sort.Slice(b.NonDrawn, func(i, j int) bool { return gapLess(b.NonDrawn[i], b.NonDrawn[j]) })
+}
+
+// compare reports every difference between a fresh measurement and the baseline.
+func (b *Baseline) compare(fresh *Baseline) error {
+	want, err := encodeBaseline(fresh)
+	if err != nil {
+		return err
+	}
+	have, err := encodeBaseline(b)
+	if err != nil {
+		return err
+	}
+	if bytes.Equal(want, have) {
+		return nil
+	}
+	var problems []string
+	if b.Source != fresh.Source {
+		problems = append(problems, fmt.Sprintf("source %+v, measured %+v", b.Source, fresh.Source))
+	}
+	if b.Totals != fresh.Totals {
+		problems = append(problems, fmt.Sprintf("totals %+v, measured %+v", b.Totals, fresh.Totals))
+	}
+	recorded := map[string]Gap{}
+	for _, g := range b.NonDrawn {
+		recorded[g.Name] = g
+	}
+	measured := map[string]Gap{}
+	for _, g := range fresh.NonDrawn {
+		measured[g.Name] = g
+		if r, ok := recorded[g.Name]; !ok {
+			problems = append(problems, fmt.Sprintf("%s (%s) is %s but the baseline records it drawn", g.Name, g.Clause, g.Verdict))
+		} else if r != g {
+			problems = append(problems, fmt.Sprintf("%s: recorded %+v, measured %+v", g.Name, r, g))
+		}
+	}
+	for _, g := range b.NonDrawn {
+		if _, ok := measured[g.Name]; !ok {
+			problems = append(problems, fmt.Sprintf("%s (%s) is recorded %s but measured drawn or absent", g.Name, g.Clause, g.Verdict))
+		}
+	}
+	if len(problems) == 0 {
+		problems = append(problems, "the clause or category counts differ")
+	}
+	sort.Strings(problems)
+	return fmt.Errorf("%s differs from the measurement; re-record with -measure:\n  %s", baselinePath, strings.Join(problems, "\n  "))
+}

+package notation
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"strings"
+)
+
+// The census document carries generated blocks between census:begin/end
+// markers: -measure writes them and -check refuses a hand-edited block.
+var generatedBlocks = []string{"source", "summary", "clauses", "gaps", "packages", "exclusions"}
+
+func blockMarker(name, which string) string {
+	return "<!-- census:" + which + " " + name + " -->"
+}
+
+func renderBlock(name string, b *Baseline) (string, error) {
+	switch name {
+	case "source":
+		return renderSource(b), nil
+	case "summary":
+		return renderSummary(b), nil
+	case "clauses":
+		return renderClauses(b), nil
+	case "gaps":
+		return renderGaps(b), nil
+	case "packages":
+		return renderPackages(b), nil
+	case "exclusions":
+		return renderExclusions(b), nil
+	}
+	return "", fmt.Errorf("unknown census block %q", name)
+}
+
+func renderSource(b *Baseline) string {
+	s := b.Source
+	return fmt.Sprintf("Measured over `%s`, rendered with `pdftotext -layout` from the SysML v2 specification PDF of pilot release `%s` (SysML-v2-Release commit `%s`), clause §%s.",
+		s.Text, s.PilotTag, s.ReleaseCommit, s.Clause)
+}
+
+func renderSummary(b *Baseline) string {
+	t := b.Totals
+	var sb strings.Builder
+	fmt.Fprintf(&sb, "%d production statements (%d of them partial `=|` statements) name %d distinct productions: **%d drawn**, **%d approximate**, **%d undrawn**, %d not applicable.\n\n",
+		t.Statements, t.PartialStatements, t.Productions, t.Drawn, t.Approximate, t.Undrawn, t.NotApplicable)
+	sb.WriteString("| Category | Productions |\n| --- | --- |\n")
+	for _, c := range Categories {
+		fmt.Fprintf(&sb, "| %s | %d |\n", c, b.Categories[string(c)])
+	}
+	return strings.TrimRight(sb.String(), "\n")
+}
+
+func renderClauses(b *Baseline) string {
+	var sb strings.Builder
+	sb.WriteString("| Clause | Statements | Productions | Drawn | Approximate | Undrawn | Not applicable |\n| --- | --- | --- | --- | --- | --- | --- |\n")
+	for _, c := range b.Clauses {
+		fmt.Fprintf(&sb, "| §%s %s | %d | %d | %d | %d | %d | %d |\n", c.Number, escape(c.Title), c.Statements, c.Productions, c.Drawn, c.Approximate, c.Undrawn, c.NotApplicable)
+	}
+	t := b.Totals
+	fmt.Fprintf(&sb, "| **Total** | %d | %d | %d | %d | %d | %d |", t.Statements, t.Productions, t.Drawn, t.Approximate, t.Undrawn, t.NotApplicable)
+	return sb.String()
+}
+
+// renderGaps lists the undrawn and approximate rows under their clause.
+func renderGaps(b *Baseline) string {
+	var sb strings.Builder
+	for _, c := range b.Clauses {
+		var rows []Gap
+		for _, g := range b.NonDrawn {
+			if g.Clause == c.Number && g.Verdict != VerdictNotApplicable {
+				rows = append(rows, g)
+			}
+		}
+		if len(rows) == 0 {
+			continue
+		}
+		fmt.Fprintf(&sb, "#### §%s %s\n\n| Production | Category | Verdict | Package | Reason |\n| --- | --- | --- | --- | --- |\n", c.Number, escape(c.Title))
+		for _, g := range rows {
+			fmt.Fprintf(&sb, "| `%s`%s | %s | %s | %s | %s |\n", g.Name, partialMark(g.Partial), g.Category, g.Verdict, g.Package, escape(g.Reason))
+		}
+		sb.WriteString("\n")
+	}
+	return strings.TrimRight(sb.String(), "\n")
+}
+
+func partialMark(partial bool) string {
+	if partial {
+		return " (partial)"
+	}
+	return ""
+}
+
+func renderPackages(b *Baseline) string {
+	var sb strings.Builder
+	sb.WriteString("| Package | Scope | Undrawn | Approximate | Productions |\n| --- | --- | --- | --- | --- |\n")
+	for _, p := range packageTitles {
+		var undrawn, approximate int
+		var names []string
+		for _, g := range b.NonDrawn {
+			if g.Package != p.Letter {
+				continue
+			}
+			names = append(names, "`"+g.Name+"`")
+			if g.Verdict == VerdictUndrawn {
+				undrawn++
+			} else {
+				approximate++
+			}
+		}
+		fmt.Fprintf(&sb, "| %s | %s | %d | %d | %s |\n", p.Letter, p.Title, undrawn, approximate, strings.Join(names, ", "))
+	}
+	return strings.TrimRight(sb.String(), "\n")
+}
+
+// renderExclusions lists the not-applicable rows grouped by their reason.
+func renderExclusions(b *Baseline) string {
+	var reasons []string
+	byReason := map[string][]string{}
+	for _, g := range b.NonDrawn {
+		if g.Verdict != VerdictNotApplicable {
+			continue
+		}
+		if _, ok := byReason[g.Reason]; !ok {
+			reasons = append(reasons, g.Reason)
+		}
+		byReason[g.Reason] = append(byReason[g.Reason], fmt.Sprintf("`%s` (§%s)", g.Name, g.Clause))
+	}
+	var sb strings.Builder
+	for _, reason := range reasons {
+		fmt.Fprintf(&sb, "- **%s** (%d): %s\n", reason, len(byReason[reason]), strings.Join(byReason[reason], ", "))
+	}
+	return strings.TrimRight(sb.String(), "\n")
+}
+
+func escape(s string) string { return strings.ReplaceAll(s, "|", `\|`) }
+
+func rewriteBlocks(content string, b *Baseline) (string, error) {
+	for _, name := range generatedBlocks {
+		rendered, err := renderBlock(name, b)
+		if err != nil {
+			return "", err
+		}
+		begin, end := blockMarker(name, "begin"), blockMarker(name, "end")
+		bi, ei := strings.Index(content, begin), strings.Index(content, end)
+		if bi < 0 || ei < 0 || ei < bi {
+			return "", fmt.Errorf("%s: missing or misordered %s / %s markers", censusDocPath, begin, end)
+		}
+		if strings.Count(content, begin) != 1 || strings.Count(content, end) != 1 {
+			return "", fmt.Errorf("%s: the census:%s block markers repeat", censusDocPath, name)
+		}
+		content = content[:bi+len(begin)] + "\n" + rendered + "\n" + content[ei:]
+	}
+	return content, nil
+}
+
+func readDocument(root string) (string, error) {
+	content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(censusDocPath))) // #nosec G304 -- fixed repository path
+	return string(content), err
+}
+
+func writeDocument(root string, b *Baseline) error {
+	content, err := readDocument(root)
+	if err != nil {
+		return err
+	}
+	rewritten, err := rewriteBlocks(content, b)
+	if err != nil {
+		return err
+	}
+	if rewritten == content {
+		return nil
+	}
+	return os.WriteFile(filepath.Join(root, filepath.FromSlash(censusDocPath)), []byte(rewritten), 0o644) // #nosec G306 -- a committed documentation file
+}
+
+func checkDocument(content string, b *Baseline) error {
+	rewritten, err := rewriteBlocks(content, b)
+	if err != nil {
+		return err
+	}
+	if rewritten != content {
+		return fmt.Errorf("%s: a generated block is stale; run `go run -C tools ./cmd/notation-census -measure`", censusDocPath)
+	}
+	return nil
+}
+
+// writeRows writes every row with its evidence to the build directory, the
+// full table the committed baseline summarises.
+func writeRows(root string, c *Census) error {
+	var sb strings.Builder
+	sb.WriteString("| Clause | Production | Statements | Category | Verdict | Implementation | Forms | Test | Reason |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
+	for _, r := range c.Rows {
+		fmt.Fprintf(&sb, "| %s | `%s`%s | %d | %s | %s | %s | %s | %s | %s |\n", r.Clause, r.Name, partialMark(r.Partial), r.Statements,
+			r.Category, r.Verdict, code(r.Implementation), strings.Join(r.Forms, ", "), code(r.Test), escape(r.Reason))
+	}
+	path := filepath.Join(root, filepath.FromSlash(rowsPath))
+	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
+		return err
+	}
+	return os.WriteFile(path, []byte(sb.String()), 0o644) // #nosec G306 -- a build report
+}
+
+func code(s string) string {
+	if s == "" {
+		return ""
+	}
+	return "`" + s + "`"
+}

+package notation
+
+import (
+	"fmt"
+	"go/ast"
+	"go/parser"
+	"go/token"
+	"os"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"strings"
+)
+
+// A citation is `path:Name`: a Go file and the function or method it declares,
+// a TypeScript file and the function it declares, or a golden file on its own.
+var (
+	goCite     = regexp.MustCompile(`^([A-Za-z0-9_./-]+\.go):([A-Za-z_][A-Za-z0-9_]*)$`)
+	tsCite     = regexp.MustCompile(`^([A-Za-z0-9_./-]+\.ts):([A-Za-z_][A-Za-z0-9_]*)$`)
+	goldenCite = regexp.MustCompile(`^[A-Za-z0-9_./-]+/testdata/[A-Za-z0-9_.-]+\.golden$`)
+)
+
+func sortStrings(s []string) { sort.Strings(s) }
+
+// declarations parses each cited Go file once.
+type declarations struct {
+	root  string
+	files map[string]map[string]bool
+}
+
+func newDeclarations(root string) *declarations {
+	return &declarations{root: root, files: map[string]map[string]bool{}}
+}
+
+// declared reports whether file declares a function or method named name.
+func (d *declarations) declared(file, name string) (bool, error) {
+	names, ok := d.files[file]
+	if !ok {
+		fset := token.NewFileSet()
+		parsed, err := parser.ParseFile(fset, filepath.Join(d.root, filepath.FromSlash(file)), nil, parser.SkipObjectResolution)
+		if err != nil {
+			return false, err
+		}
+		names = map[string]bool{}
+		for _, decl := range parsed.Decls {
+			if fn, ok := decl.(*ast.FuncDecl); ok {
+				names[fn.Name.Name] = true
+			}
+		}
+		d.files[file] = names
+	}
+	return names[name], nil
+}
+
+// resolve checks one citation against the repository.
+func (d *declarations) resolve(cite string, test bool) error {
+	if m := goCite.FindStringSubmatch(cite); m != nil {
+		if test != strings.HasSuffix(m[1], "_test.go") || test && !strings.HasPrefix(m[2], "Test") {
+			return fmt.Errorf("%s: an implementation cites a non-test function, a test cites func TestX in a _test.go file", cite)
+		}
+		ok, err := d.declared(m[1], m[2])
+		if err != nil {
+			return err
+		}
+		if !ok {
+			return fmt.Errorf("%s declares no function %s", m[1], m[2])
+		}
+		return nil
+	}
+	if m := tsCite.FindStringSubmatch(cite); m != nil && !test {
+		content, err := os.ReadFile(filepath.Join(d.root, filepath.FromSlash(m[1]))) // #nosec G304 -- the path is a citation under the repository root
+		if err != nil {
+			return err
+		}
+		if !regexp.MustCompile(`\bfunction ` + m[2] + `\b`).Match(content) {
+			return fmt.Errorf("%s declares no function %s", m[1], m[2])
+		}
+		return nil
+	}
+	if test && goldenCite.MatchString(cite) {
+		if _, err := os.Stat(filepath.Join(d.root, filepath.FromSlash(cite))); err != nil {
+			return err
+		}
+		return nil
+	}
+	return fmt.Errorf("%q is not a citation: want file.go:Func, file.ts:func, file_test.go:TestX or a testdata/*.golden path", cite)
+}
+
+// CheckEvidence resolves every citation of the drawn and approximate rows and
+// checks their forms; the problems are sorted by production.
+func CheckEvidence(root string, rows []Row) []string {
+	decls := newDeclarations(root)
+	known := map[string]bool{}
+	for _, f := range Forms {
+		known[f] = true
+	}
+	var problems []string
+	for _, r := range rows {
+		switch r.Verdict {
+		case VerdictDrawn, VerdictApproximate:
+		default:
+			if r.Implementation != "" || r.Test != "" || len(r.Forms) > 0 {
+				problems = append(problems, fmt.Sprintf("%s: a %s row carries evidence", r.Name, r.Verdict))
+			}
+			continue
+		}
+		if r.Implementation == "" || r.Test == "" || len(r.Forms) == 0 {
+			problems = append(problems, fmt.Sprintf("%s: a %s row needs an implementation, forms and a test", r.Name, r.Verdict))
+			continue
+		}
+		if err := decls.resolve(r.Implementation, false); err != nil {
+			problems = append(problems, fmt.Sprintf("%s: %v", r.Name, err))
+		}
+		if err := decls.resolve(r.Test, true); err != nil {
+			problems = append(problems, fmt.Sprintf("%s: %v", r.Name, err))
+		}
+		for _, f := range r.Forms {
+			if !known[f] {
+				problems = append(problems, fmt.Sprintf("%s: unknown form %q", r.Name, f))
+			}
+		}
+	}
+	sort.Strings(problems)
+	return problems
+}

+// Package notation is the census of the SysML v2 graphical notation (§8.2.3):
+// it extracts the clause's BNF productions from the rendered specification,
+// adjudicates each against what the view renderers draw, and holds a committed
+// baseline to the measurement.
+package notation
+
+import (
+	"fmt"
+	"regexp"
+	"sort"
+	"strconv"
+	"strings"
+)
+
+// The clause the census measures, as the rendered specification heads it, and
+// the heading that follows it; both are matched as whole lines.
+const (
+	clausePrefix   = "8.2.3."
+	overviewTitle  = "8.2.3.1 Graphical Notation Overview"
+	nextClauseHead = "8.3 Abstract Syntax"
+	clauseCount    = 27
+)
+
+// A production statement is `name =` (complete) or `name =|` (partial), the
+// name lowercase with internal hyphens, at the start of a line. pdftotext
+// starts a page with a form feed, which may precede a statement or a heading.
+var (
+	statementLine = regexp.MustCompile(`^\f?([a-z][a-z0-9-]*) =(\|?)(?:\s|$)`)
+	headingLine   = regexp.MustCompile(`^\f?8\.2\.3\.([0-9]+) ((?:[A-Za-z,-]+ )*Graphical Notation(?: Overview)?)$`)
+)
+
+// Statement is one production statement of the graphical BNF.
+type Statement struct {
+	Clause  string // the clause number, "8.2.3.4"
+	Name    string
+	Partial bool // `=|`: the production adds alternatives to one stated elsewhere
+	Line    int  // 1-based line in the rendered text
+}
+
+// Production is one named production: every statement of its name, the clause
+// of the first and whether any statement defines it completely.
+type Production struct {
+	Name       string   `json:"name"`
+	Clause     string   `json:"clause"`
+	Partial    bool     `json:"partial,omitempty"`
+	Statements int      `json:"statements"`
+	Clauses    []string `json:"clauses,omitempty"`
+}
+
+// Clause is one sub-clause of §8.2.3 with its title and statement count.
+type Clause struct {
+	Number     string `json:"number"`
+	Title      string `json:"title"`
+	Statements int    `json:"statements"`
+}
+
+// Grammar is the extracted graphical BNF: the clauses in order, the statements
+// in text order and the productions by first appearance.
+type Grammar struct {
+	Clauses     []Clause
+	Statements  []Statement
+	Productions []Production
+}
+
+// Extract reads the §8.2.3 graphical BNF out of the rendered specification text.
+// It fails when the clause's bounds or any of its 27 sub-clause headings are
+// missing, when the overview states a production or a later clause none: a text
+// from another pin or rendering must not pass as a changed denominator.
+func Extract(text string) (*Grammar, error) {
+	lines := strings.Split(text, "\n")
+	start, end, err := clauseBounds(lines)
+	if err != nil {
+		return nil, err
+	}
+	g := &Grammar{}
+	byName := map[string]int{}
+	clause := 0
+	for i := start; i < end; i++ {
+		line := strings.TrimRight(lines[i], " \r")
+		if m := headingLine.FindStringSubmatch(line); m != nil {
+			n, _ := strconv.Atoi(m[1])
+			if n != len(g.Clauses)+1 {
+				return nil, fmt.Errorf("line %d: clause %s%s follows %d sub-clauses; the headings must run 1..%d in order", i+1, clausePrefix, m[1], len(g.Clauses), clauseCount)
+			}
+			g.Clauses = append(g.Clauses, Clause{Number: clausePrefix + m[1], Title: m[2]})
+			clause = len(g.Clauses) - 1
+			continue
+		}
+		m := statementLine.FindStringSubmatch(line)
+		if m == nil {
+			continue
+		}
+		st := Statement{Clause: g.Clauses[clause].Number, Name: m[1], Partial: m[2] == "|", Line: i + 1}
+		g.Statements = append(g.Statements, st)
+		g.Clauses[clause].Statements++
+		if j, ok := byName[st.Name]; ok {
+			p := &g.Productions[j]
+			p.Statements++
+			if !st.Partial {
+				p.Partial = false
+			}
+			if p.Clauses[len(p.Clauses)-1] != st.Clause {
+				p.Clauses = append(p.Clauses, st.Clause)
+			}
+			continue
+		}
+		byName[st.Name] = len(g.Productions)
+		g.Productions = append(g.Productions, Production{Name: st.Name, Clause: st.Clause, Partial: st.Partial, Statements: 1, Clauses: []string{st.Clause}})
+	}
+	if len(g.Clauses) != clauseCount {
+		return nil, fmt.Errorf("found %d sub-clause headings of §8.2.3, want %d", len(g.Clauses), clauseCount)
+	}
+	if g.Clauses[0].Statements != 0 {
+		return nil, fmt.Errorf("%s states a production; the rendered text does not match the pinned specification", overviewTitle)
+	}
+	for _, c := range g.Clauses[1:] {
+		if c.Statements == 0 {
+			return nil, fmt.Errorf("%s %s states no production; the rendered text does not match the pinned specification", c.Number, c.Title)
+		}
+	}
+	for i := range g.Productions {
+		if len(g.Productions[i].Clauses) == 1 {
+			g.Productions[i].Clauses = nil
+		}
+	}
+	return g, nil
+}
+
+// clauseBounds finds the overview heading and the heading of the clause after
+// §8.2.3, skipping the table of contents, whose lines carry page numbers.
+func clauseBounds(lines []string) (start, end int, err error) {
+	start = -1
+	for i, line := range lines {
+		line = strings.TrimRight(strings.TrimPrefix(line, "\f"), " \r")
+		if start < 0 {
+			if line == overviewTitle {
+				start = i
+			}
+			continue
+		}
+		if line == nextClauseHead {
+			return start, i, nil
+		}
+	}
+	if start < 0 {
+		return 0, 0, fmt.Errorf("the rendered text has no %q heading line", overviewTitle)
+	}
+	return 0, 0, fmt.Errorf("the rendered text has no %q heading after %q", nextClauseHead, overviewTitle)
+}
+
+// ProductionNames lists the production names in sorted order.
+func (g *Grammar) ProductionNames() []string {
+	names := make([]string, 0, len(g.Productions))
+	for _, p := range g.Productions {
+		names = append(names, p.Name)
+	}
+	sort.Strings(names)
+	return names
+}
+
+// Partials counts the partial `=|` statements.
+func (g *Grammar) Partials() int {
+	n := 0
+	for _, st := range g.Statements {
+		if st.Partial {
+			n++
+		}
+	}
+	return n
+}

+package notation
+
+import (
+	"os"
+	"path/filepath"
+	"strconv"
+	"strings"
+	"testing"
+)
+
+// excerptPath is the committed excerpt of the rendered specification: every
+// §8.2.3 heading and production statement of the pinned text, each statement
+// cut after its `=`, with its page-start form feeds and a few page footers.
+const excerptPath = "testdata/sysml-8.2.3-productions.txt"
+
+func readExcerpt(t *testing.T) string {
+	t.Helper()
+	content, err := os.ReadFile(excerptPath)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return string(content)
+}
+
+func TestExtractTheCommittedExcerpt(t *testing.T) {
+	g, err := Extract(readExcerpt(t))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(g.Clauses) != 27 || len(g.Statements) != 620 || len(g.Productions) != 523 || g.Partials() != 97 {
+		t.Fatalf("clauses %d statements %d productions %d partials %d; want 27, 620, 523, 97",
+			len(g.Clauses), len(g.Statements), len(g.Productions), g.Partials())
+	}
+	if g.Clauses[0].Statements != 0 || g.Clauses[0].Title != "Graphical Notation Overview" {
+		t.Errorf("overview: %+v", g.Clauses[0])
+	}
+	annotations := g.Clauses[3]
+	if annotations.Number != "8.2.3.4" || annotations.Title != "Annotations Graphical Notation" || annotations.Statements != 12 {
+		t.Errorf("the form-feed-prefixed §8.2.3.4 heading: %+v", annotations)
+	}
+	byName := map[string]Production{}
+	for _, p := range g.Productions {
+		byName[p.Name] = p
+	}
+	if p := byName["ellipsis-at-lower-left-corner"]; p.Clause != "8.2.3.2" {
+		t.Errorf("a statement at the start of a page is kept: %+v", p)
+	}
+	if p := byName["compartment"]; !p.Partial || p.Statements != 24 || len(p.Clauses) < 20 {
+		t.Errorf("compartment is a partial production extended in most clauses: %+v", p)
+	}
+	if p := byName["usage-node"]; p.Partial || p.Statements != 19 {
+		t.Errorf("usage-node has a complete statement among its partial ones: %+v", p)
+	}
+	if p := byName["comment-node"]; p.Clause != "8.2.3.4" || p.Partial || p.Clauses != nil {
+		t.Errorf("comment-node: %+v", p)
+	}
+}
+
+func TestExtractIsDeterministic(t *testing.T) {
+	text := readExcerpt(t)
+	a, err := Extract(text)
+	if err != nil {
+		t.Fatal(err)
+	}
+	b, _ := Extract(text)
+	if strings.Join(a.ProductionNames(), ",") != strings.Join(b.ProductionNames(), ",") || len(a.Statements) != len(b.Statements) {
+		t.Fatal("two extractions differ")
+	}
+}
+
+func TestExtractRejectsAChangedText(t *testing.T) {
+	text := readExcerpt(t)
+	cases := []struct {
+		name   string
+		mutate func(string) string
+		want   string
+	}{
+		{"no overview heading", func(s string) string { return strings.Replace(s, overviewTitle, "8.2.3.1 Overview", 1) }, "no \"8.2.3.1 Graphical Notation Overview\" heading"},
+		{"no next clause", func(s string) string { return strings.Replace(s, nextClauseHead, "8.3 Abstract", 1) }, "no \"8.3 Abstract Syntax\" heading"},
+		{"a clause heading lost", func(s string) string { return strings.Replace(s, "\f8.2.3.4 Annotations Graphical Notation", "", 1) }, "clause 8.2.3.5 follows 3 sub-clauses"},
+		{"a clause without productions", func(s string) string {
+			return strings.Replace(s, "8.2.3.22 Cases Graphical Notation\ncompartment =|\nobjective-compartment =\nobjective-compartment-contents =\nobjective-compartment-element =\n", "8.2.3.22 Cases Graphical Notation\n", 1)
+		}, "8.2.3.22 Cases Graphical Notation states no production"},
+		{"a production in the overview", func(s string) string {
+			return strings.Replace(s, overviewTitle+"\n", overviewTitle+"\nearly-node =\n", 1)
+		}, "8.2.3.1 Graphical Notation Overview states a production"},
+		{"a heading out of order", func(s string) string { return strings.Replace(s, "8.2.3.3 Dependencies", "8.2.3.5 Dependencies", 1) }, "follows 2 sub-clauses"},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			mutated := tc.mutate(text)
+			if mutated == text {
+				t.Fatal("the mutation changed nothing")
+			}
+			_, err := Extract(mutated)
+			if err == nil || !strings.Contains(err.Error(), tc.want) {
+				t.Fatalf("got %v, want an error containing %q", err, tc.want)
+			}
+		})
+	}
+}
+
+func TestExtractIgnoresRightHandSidesAndFooters(t *testing.T) {
+	text := strings.Join([]string{
+		overviewTitle,
+		"8.2.3.2 Elements and Relationships Graphical Notation",
+		"element = part | item",
+		"Systems Modeling Language v2.1, Beta 2, Part 1                          209",
+		"\fcompartment =| general-compartment",
+		"general-compartment = compartment-label = ignored",
+	}, "\n")
+	for n := 3; n <= clauseCount; n++ {
+		text += "\n8.2.3." + itoa(n) + " Filler Graphical Notation\nfiller-" + itoa(n) + " ="
+	}
+	text += "\n" + nextClauseHead + "\n"
+	g, err := Extract(text)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if got := strings.Join(g.ProductionNames()[:3], ","); got != "compartment,element,filler-10" {
+		t.Errorf("productions %q", got)
+	}
+	if g.Clauses[1].Statements != 3 {
+		t.Errorf("§8.2.3.2 counts %d statements, want 3", g.Clauses[1].Statements)
+	}
+}
+
+func itoa(n int) string { return strconv.Itoa(n) }
+
+func TestExcerptIsUnderTheFixtureCap(t *testing.T) {
+	info, err := os.Stat(filepath.FromSlash(excerptPath))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if info.Size() > 200<<10 {
+		t.Fatalf("%s is %d bytes, over the tests/hygiene fixture cap", excerptPath, info.Size())
+	}
+}

+package notation
+
+import (
+	"errors"
+	"flag"
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"strings"
+
+	"github.com/Open-MBEE/OpenSysML/tools/oracle/baseline"
+	"github.com/Open-MBEE/OpenSysML/tools/oracle/repo"
+)
+
+// RequireEnv is the workflow variable that makes an absent specification text
+// a failure rather than a skipped comparison; the spec-examples gate sets it.
+const RequireEnv = "OPENSYSML_REQUIRE_SPEC_EXAMPLES"
+
+type options struct {
+	text        string
+	requireText bool
+}
+
+// Main runs the notation census command: -measure re-measures the census into
+// the baseline and the document, -check verifies both against the repository
+// and, where the rendered text is present, against a fresh measurement.
+func Main(args []string, stdout, stderr io.Writer) int {
+	flags := flag.NewFlagSet("notation-census", flag.ContinueOnError)
+	flags.SetOutput(stderr)
+	repoDir := flags.String("repo", "", "repository root (default: the module root above the working directory)")
+	text := flags.String("text", "", "rendered specification text (default: "+defaultTextPath+", as scripts/download-spec-examples.sh renders it)")
+	check := flags.Bool("check", false, "verify the baseline, the census document and the evidence agree, and the measurement where the text is present")
+	measure := flags.Bool("measure", false, "re-measure the census into the baseline and the document")
+	requireText := flags.Bool("require-text", false, "fail rather than skip the measurement when the rendered text is absent")
+	if err := flags.Parse(args); err != nil {
+		if err == flag.ErrHelp {
+			return 0
+		}
+		return 2
+	}
+	if flags.NArg() != 0 {
+		fmt.Fprintf(stderr, "notation-census: unexpected argument %q\n", flags.Arg(0))
+		return 2
+	}
+	if *check && *measure {
+		fmt.Fprintln(stderr, "notation-census: -check and -measure exclude each other")
+		return 2
+	}
+	root, err := repo.Choose(*repoDir)
+	if err != nil {
+		fmt.Fprintf(stderr, "notation-census: %v\n", err)
+		return 1
+	}
+	opts := options{text: repo.Resolve(root, *text), requireText: *requireText || os.Getenv(RequireEnv) != ""}
+	if opts.text == "" {
+		opts.text = filepath.Join(root, filepath.FromSlash(defaultTextPath))
+	}
+	if *check {
+		err = runCheck(root, opts, stdout)
+	} else {
+		err = runMeasure(root, opts, stdout)
+	}
+	if err != nil {
+		fmt.Fprintf(stderr, "notation-census: %v\n", err)
+		return 1
+	}
+	return 0
+}
+
+func textRel(root, text string) string {
+	if rel, err := filepath.Rel(root, text); err == nil && !strings.HasPrefix(rel, "..") {
+		return filepath.ToSlash(rel)
+	}
+	return filepath.ToSlash(text)
+}
+
+func runMeasure(root string, opts options, out io.Writer) error {
+	source, err := ReadSource(root, textRel(root, opts.text))
+	if err != nil {
+		return err
+	}
+	c, err := Measure(root, opts.text)
+	if err != nil {
+		return err
+	}
+	if problems := CheckEvidence(root, c.Rows); len(problems) > 0 {
+		return fmt.Errorf("the evidence does not resolve:\n  %s", strings.Join(problems, "\n  "))
+	}
+	b := c.Baseline(source)
+	b.sortNonDrawn()
+	if err := writeBaseline(root, b); err != nil {
+		return err
+	}
+	if err := writeDocument(root, b); err != nil {
+		return err
+	}
+	if err := writeRows(root, c); err != nil {
+		return err
+	}
+	t := b.Totals
+	fmt.Fprintf(out, "notation-census: %d productions (%d statements): %d drawn, %d approximate, %d undrawn, %d not applicable; wrote %s, %s and %s\n",
+		t.Productions, t.Statements, t.Drawn, t.Approximate, t.Undrawn, t.NotApplicable, baselinePath, censusDocPath, rowsPath)
+	return nil
+}
+
+func runCheck(root string, opts options, out io.Writer) error {
+	b, err := loadBaseline(root)
+	if err != nil {
+		return err
+	}
+	var failures []string
+	for _, err := range []error{
+		b.validate(),
+		checkPin(root, b),
+		checkDocumentFile(root, b),
+		checkStaticEvidence(root),
+		checkMeasurement(root, b, opts, out),
+	} {
+		if err != nil {
+			failures = append(failures, err.Error())
+		}
+	}
+	if len(failures) > 0 {
+		return errors.New(strings.Join(failures, "\n"))
+	}
+	fmt.Fprintf(out, "notation-census: %d productions, baseline, census document and evidence agree\n", b.Totals.Productions)
+	return nil
+}
+
+// checkPin verifies the baseline records the pinned pilot release, and the
+// downloaded PDFs' pin where they are present.
+func checkPin(root string, b *Baseline) error {
+	pin, err := baseline.ReadPin(root)
+	if err != nil {
+		return err
+	}
+	if b.Source.PilotTag != pin.Tag {
+		return fmt.Errorf("%s records pilot tag %s but %s pins %s: re-measure", baselinePath, b.Source.PilotTag, baseline.PinPath, pin.Tag)
+	}
+	content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(specPinPath))) // #nosec G304 -- fixed repository path
+	if errors.Is(err, os.ErrNotExist) {
+		return nil
+	}
+	if err != nil {
+		return err
+	}
+	if fields := strings.Fields(string(content)); len(fields) < 2 || fields[0] != b.Source.PilotTag || fields[1] != b.Source.ReleaseCommit {
+		return fmt.Errorf("%s pins %q but %s records %s %s", specPinPath, strings.TrimSpace(string(content)), baselinePath, b.Source.PilotTag, b.Source.ReleaseCommit)
+	}
+	return nil
+}
+
+func checkDocumentFile(root string, b *Baseline) error {
+	content, err := readDocument(root)
+	if err != nil {
+		return err
+	}
+	return checkDocument(content, b)
+}
+
+// checkStaticEvidence resolves the citations of the verdict table and of the
+// notation table's rows, which need no specification text.
+func checkStaticEvidence(root string) error {
+	edges, err := ReadNotationTable(root)
+	if err != nil {
+		return err
+	}
+	var rows []Row
+	for _, name := range AdjudicatedNames() {
+		rows = append(rows, Row{Production: Production{Name: name}, Adjudication: table[name]})
+	}
+	for _, name := range edges.Names() {
+		adj, _ := edges.adjudicate(name)
+		rows = append(rows, Row{Production: Production{Name: name}, Adjudication: adj})
+	}
+	if problems := CheckEvidence(root, rows); len(problems) > 0 {
+		return fmt.Errorf("the evidence does not resolve:\n  %s", strings.Join(problems, "\n  "))
+	}
+	return nil
+}
+
+// checkMeasurement compares a fresh measurement with the baseline where the
+// rendered text is present; absent, it skips unless the text is required.
+func checkMeasurement(root string, b *Baseline, opts options, out io.Writer) error {
+	if _, err := os.Stat(opts.text); errors.Is(err, os.ErrNotExist) {
+		if opts.requireText {
+			return fmt.Errorf("%s is absent and required (-require-text or %s): run scripts/download-spec-examples.sh", textRel(root, opts.text), RequireEnv)
+		}
+		fmt.Fprintf(out, "notation-census: %s is absent; the measurement comparison is skipped\n", textRel(root, opts.text))
+		return nil
+	} else if err != nil {
+		return err
+	}
+	source, err := ReadSource(root, textRel(root, opts.text))
+	if err != nil {
+		return err
+	}
+	c, err := Measure(root, opts.text)
+	if err != nil {
+		return err
+	}
+	fresh := c.Baseline(source)
+	fresh.sortNonDrawn()
+	return b.compare(fresh)
+}

